import { Link, useLocation } from 'react-router-dom'
import withStyles from './jss'
import LogoutButton from './logout-button'

function capitalizeFirstLetter(string) {
  return string.charAt(0).toUpperCase() + string.slice(1)
}

function Header({ classes, paths }) {
  const loggedIn = localStorage.getItem('token') !== null

  const categories = ['crypto', 'misc', 'osint', 'pwn', 'rev', 'web']
  const links = {
    // '/': 'Home',
    '/scores': 'Scoreboard',
    '/challs': 'Challenges',
    ...Object.fromEntries(
      categories.map(category => [
        `/challs/${category}`,
        capitalizeFirstLetter(category),
      ])
    ),
  }

  const location = useLocation()
  console.log(location)

  return (
    <div className={classes.mainContainer}>
      <div className={classes.logoList}>
        <Link to='/'>
          <div className={classes.logoListContainer}>
            <img
              className={classes.logoImg}
              src='https://static.umdctf.io/logo-2026.png'
            />
            <h3>umdctf</h3>
          </div>
        </Link>
        <div className={classes.accentedRowContainer}>
          {loggedIn ? (
            <>
              <LogoutButton className={classes.link} />
              <Link to='/profile' className={classes.link}>
                Profile
              </Link>
            </>
          ) : (
            <>
              <Link to='/login' className={classes.link}>
                Log in
              </Link>
              <Link to='/register' className={classes.link}>
                Sign up
              </Link>
            </>
          )}
        </div>
      </div>
      <div className={classes.rowContainer}>
        {Object.entries(links).map(([path, title]) => (
          <Link
            to={path}
            className={`${classes.link} ${
              path === location.pathname && classes.linkActive
            }`}
            key={path}
          >
            {title}
          </Link>
        ))}
      </div>
    </div>
  )
}

