import { useCallback, useState, useEffect, useMemo } from 'preact/hooks'
import { useParams } from 'react-router-dom'

import config from '../config'
import withStyles from '../components/jss'
import Problem from '../components/problem'
import NotStarted from '../components/not-started'
import { useToast } from '../components/toast'

import { getChallenges, getNumTeams, getPrivateSolves } from '../api/challenges'

const loadStates = {
  pending: 0,
  notStarted: 1,
  loaded: 2,
}

const Challenges = ({ classes }) => {
  const { category } = useParams()
  console.log(category)

  const [problems, setProblems] = useState(null)
  const [numTeams, setNumTeams] = useState(null)

  const [solveIDs, setSolveIDs] = useState([])
  const [loadState, setLoadState] = useState(loadStates.pending)
  const { toast } = useToast()

  const setSolved = useCallback(id => {
    setSolveIDs(solveIDs => {
      if (!solveIDs.includes(id)) {
        return [...solveIDs, id]
      }
      return solveIDs
    })
  }, [])

  useEffect(() => {
    document.title = `Challenges | ${config.ctfName}`
  }, [])

  useEffect(() => {
    const action = async () => {
      if (problems !== null) {
        return
      }
      const { data, error, notStarted } = await getChallenges()
      if (error) {
        toast({ body: error, type: 'error' })
        return
      }

      setLoadState(notStarted ? loadStates.notStarted : loadStates.loaded)
      if (notStarted) {
        return
      }

      setProblems(data)
    }
    action()
  }, [toast, problems])

  useEffect(() => {
    const action = async () => {
      if (numTeams !== null) {
        return
      }
      const { data, error } = await getNumTeams()
      if (error) {
        toast({ body: error, type: 'error' })
        return
      }

      setNumTeams(data)
    }
    action()
  }, [toast, numTeams])

  useEffect(() => {
    const action = async () => {
      const { data, error } = await getPrivateSolves()
      if (error) {
        toast({ body: error, type: 'error' })
        return
      }

      setSolveIDs(data.map(solve => solve.id))
    }
    action()
  }, [toast])

  const problemsToDisplay = useMemo(() => {
    if (problems === null) {
      return []
    }
    let filtered = problems
    console.log(category)
    if (category) {
      filtered = filtered.filter(problem => problem.category === category)
    }

    filtered.sort((a, b) => {
      if (a.points === b.points) {
        if (a.solves === b.solves) {
          const aWeight = a.sortWeight || 0
          const bWeight = b.sortWeight || 0

          return bWeight - aWeight
        }
        return b.solves - a.solves
      }
      return a.points - b.points
    })

    return filtered
  }, [problems, category])

  if (loadState === loadStates.pending) {
    return null
  }

  if (loadState === loadStates.notStarted) {
    return <NotStarted />
  }

  return (
    <div className={`row ${classes.row}`}>
      {problemsToDisplay.map(problem => {
        return (
          <div className={`col-4 ${classes.problemContainer}`} key={problem.id}>
            <Problem
              problem={problem}
              solved={solveIDs.includes(problem.id)}
              setSolved={setSolved}
              numTeams={numTeams}
            />
          </div>
        )
      })}
      <div className={`col-4 ${classes.problemContainer}`} />
      <div className={`col-4 ${classes.problemContainer}`} />
      <div className={`col-4 ${classes.problemContainer}`} />
    </div>
  )
}

export default withStyles(
  {
    showSolved: {
      marginBottom: '0.625em',
    },
    frame: {
      marginBottom: '1em',
      paddingBottom: '0.625em',
      background: '#222',
    },
    row: {
      justifyContent: 'center',
      '& .title, & .frame__subtitle': {
        color: '#fff',
      },
      width: '100%',
    },
    problemContainer: {
      marginBottom: '18px',
    },
  },
  Challenges
)
